import { invalidId, reservedId } from "./problems.mjs";

// The spec's Reserved Path Segment Registry (Appendix C), as
// @interop/storage-core publishes it: a client-chosen id equal to one of
// these would shadow the reserved route at that position.
export const RESERVED_COLLECTION_IDS = new Set([
  "backends",
  "collections",
  "export",
  "import",
  "linkset",
  "meta",
  "policy",
  "query",
  "quotas",
  "replicas",
  "zcaps",
]);

// `meta` is reserved at the resource position because Collection Metadata is
// addressed at /space/{s}/{c}/meta.
export const RESERVED_RESOURCE_IDS = new Set([
  "backend",
  "linkset",
  "meta",
  "policy",
  "query",
  "quota",
]);

// Space ids are server-assigned bucket names, so they have their own rule.
const SPACE_ID_RE = /^dcc-was-[0-9a-f-]{36}$/;

// The one client-chosen Space id this server accepts: an unlock Space's,
// which is was-client's `deriveSpaceId` over its controller DID (the
// unpadded base64url of SHA-256 of the DID, 43 characters). The bucket
// behind such an id is named by store.mjs's `bucketOf`.
const SELF_PROVISIONED_ID_RE = /^[A-Za-z0-9_-]{43}$/;

export function isSelfProvisionedSpaceId(id) {
  return typeof id === "string" && SELF_PROVISIONED_ID_RE.test(id);
}

// Space ids no client may create by id: the reference server's own identity
// Space, kept reserved so a self-hosted `did:webvh:...:space:server:id` can
// never be claimed by a client.
export const RESERVED_SPACE_IDS = new Set(["server"]);

export function isReservedSpaceId(id) {
  return RESERVED_SPACE_IDS.has(id);
}

// Reserved segments naming optional sections this server does not
// implement: a request for one is the spec's unsupported-operation (501),
// where a method the spec does not define at a reserved endpoint is 405.
export const UNIMPLEMENTED_SEGMENTS = new Set(["linkset", "quotas", "backends", "replicas", "zcaps", "chunks"]);

// One path segment, as delivered decoded: no separator, no control
// characters, no dot segments. Anything else (spaces, commas, unicode) is
// fine because the client percent-encodes it on the wire.
const SEGMENT_RE = /^[^/\p{Cc}]{1,255}$/u;

export function isValidSpaceId(id) {
  return typeof id === "string" && (SPACE_ID_RE.test(id) || SELF_PROVISIONED_ID_RE.test(id));
}

// Throws the spec's problem for an id that is malformed (400 invalid-id) or
// reserved (409 reserved-id).
export function assertId(kind, id) {
  if (typeof id !== "string" || id === "." || id === ".." || !SEGMENT_RE.test(id)) {
    throw invalidId(`A ${kind} id must be a single non-empty path segment.`);
  }
  const reserved = kind === "collection" ? RESERVED_COLLECTION_IDS : RESERVED_RESOURCE_IDS;
  if (reserved.has(id)) {
    throw reservedId(id);
  }
}

export function isReserved(kind, id) {
  return (kind === "collection" ? RESERVED_COLLECTION_IDS : RESERVED_RESOURCE_IDS).has(id);
}

export const encodeSegment = (segment) => encodeURIComponent(segment);
